import{_ as a,o as i,c as t,an as n}from"./chunks/framework.BIzDrlen.js";const d=JSON.parse('{"title":"Signal Example — ICA 5: Sphering (Whitening)","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/teaching/ica/signal_example_ica_sphering.md","filePath":"tutorials/teaching/ica/signal_example_ica_sphering.md","lastUpdated":null}'),o={name:"tutorials/teaching/ica/signal_example_ica_sphering.md"};function s(r,e,l,h,p,c){return i(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="Signal-Example-—-ICA-5:-Sphering-Whitening" tabindex="-1">Signal Example — ICA 5: Sphering (Whitening) <a class="header-anchor" href="#Signal-Example-—-ICA-5:-Sphering-Whitening" aria-label="Permalink to &quot;Signal Example — ICA 5: Sphering (Whitening) {#Signal-Example-—-ICA-5:-Sphering-Whitening}&quot;">​</a></h1><p>This interactive visualization illustrates a key preprocessing step in ICA: <strong>sphering (whitening)</strong>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">This is Part 5 of the ICA series. It connects the correlated mixtures of Part 4 to the rotational optimization space of Part 6.</p><p></p></div><h2 id="The-Problem" tabindex="-1">The Problem <a class="header-anchor" href="#The-Problem" aria-label="Permalink to &quot;The Problem {#The-Problem}&quot;">​</a></h2><p>Raw EEG mixtures form correlated, unequally scaled, off-center distributions. Estimating an unconstrained unmixing matrix directly requires solving for centering, scaling, decorrelation, and rotation all at once.</p><h2 id="The-Solution:-Sphering" tabindex="-1">The Solution: Sphering <a class="header-anchor" href="#The-Solution:-Sphering" aria-label="Permalink to &quot;The Solution: Sphering {#The-Solution:-Sphering}&quot;">​</a></h2><p>Instead of estimating everything simultaneously, ICA algorithms first apply <strong>sphering</strong> (whitening).</p><p>This demo steps the data through the three stages of sphering:</p><ol><li><p><strong>Centering</strong>: Subtract the mean of each channel so the distribution is centered at <code>(0, 0)</code>.</p></li><li><p><strong>PCA Rotation</strong>: Rotate the principal axes of covariance to align with the coordinate axes, removing pairwise correlation.</p></li><li><p><strong>Variance Scaling (Sphering)</strong>: Rescale each axis to unit variance so the covariance matrix becomes the identity matrix.</p></li></ol><h2 id="Why-Do-We-Do-This?" tabindex="-1">Why Do We Do This? <a class="header-anchor" href="#Why-Do-We-Do-This?" aria-label="Permalink to &quot;Why Do We Do This? {#Why-Do-We-Do-This?}&quot;">​</a></h2><p>Once the data are sphered (uncorrelated with unit variance in every direction), any remaining linear unmixing transformation is an <strong>orthogonal rotation</strong>.</p><p>Dragging the <strong>Morph</strong> slider to <code>3.0</code> (Sphered) produces this isotropic search space, which leads directly into <a href="./signal_example_ica_optimization">Part 6: Inside the Black Box</a>, where rotating a projection vector through the sphered data locates the independent components.</p><h2 id="Code" tabindex="-1">Code <a class="header-anchor" href="#Code" aria-label="Permalink to &quot;Code {#Code}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EegFun</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EegFun</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">signal_example_ica_sphering</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><h2 id="See-Also" tabindex="-1">See Also <a class="header-anchor" href="#See-Also" aria-label="Permalink to &quot;See Also {#See-Also}&quot;">​</a></h2><ul><li><p><a href="./signal_example_ica_geometry">Part 4: 3 Sources &amp; Geometry</a> — Scatter plots and correlation blobs</p></li><li><p><a href="./signal_example_ica_clt">ICA: Central Limit Theorem</a> — Why mixed blobs become Gaussian</p></li><li><p><a href="./signal_example_ica_optimization">Part 6: Inside the Black Box</a> — Gradient ascent rotation</p></li></ul>`,16)])])}const m=a(o,[["render",s]]);export{d as __pageData,m as default};
